-- Sandbox-only SQL mock. It creates no background worker and performs no scheduled action.
CREATE TABLE cron.job (
  jobid bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  jobname text NOT NULL,
  schedule text NOT NULL,
  command text NOT NULL,
  active boolean NOT NULL DEFAULT true
);
CREATE FUNCTION cron.schedule(p_job_name text, p_schedule text, p_command text)
RETURNS bigint
LANGUAGE plpgsql
AS $function$
DECLARE v_id bigint;
BEGIN
  INSERT INTO cron.job(jobname, schedule, command)
  VALUES (p_job_name, p_schedule, p_command)
  RETURNING jobid INTO v_id;
  RETURN v_id;
END;
$function$;
CREATE FUNCTION cron.unschedule(p_job_id bigint)
RETURNS boolean
LANGUAGE plpgsql
AS $function$
DECLARE v_rows integer;
BEGIN
  DELETE FROM cron.job WHERE jobid = p_job_id;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows = 1;
END;
$function$;
